bool CoreTenantPreferences::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("tenant_id"))
    {
        if(!validJsonOfField(0, "tenant_id", pJson["tenant_id"], err, true))
            return false;
    }

    else
    {
        err="The tenant_id column cannot be null";
        return false;
    }

    if(pJson.isMember("settings"))
    {
        if(!validJsonOfField(1, "settings", pJson["settings"], err, true))
            return false;
    }

    else
    {
        err="The settings column cannot be null";
        return false;
    }

    if(pJson.isMember("version"))
    {
        if(!validJsonOfField(2, "version", pJson["version"], err, true))
            return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(3, "created_at", pJson["created_at"], err, true))
            return false;
    }

    if(pJson.isMember("created_by_user_id"))
    {
        if(!validJsonOfField(4, "created_by_user_id", pJson["created_by_user_id"], err, true))
            return false;
    }

    else
    {
        err="The created_by_user_id column cannot be null";
        return false;
    }

    if(pJson.isMember("last_modified_at"))
    {
        if(!validJsonOfField(5, "last_modified_at", pJson["last_modified_at"], err, true))
            return false;
    }

    if(pJson.isMember("last_modified_by_user_id"))
    {
        if(!validJsonOfField(6, "last_modified_by_user_id", pJson["last_modified_by_user_id"], err, true))
            return false;
    }

    if(pJson.isMember("is_deleted"))
    {
        if(!validJsonOfField(7, "is_deleted", pJson["is_deleted"], err, true))
            return false;
    }

    return true;
}
